#!/usr/bin/env node
/**
 * src/generated/api-schema.json -> src/generated/api-types.ts.
 *
 * The schema is GENERATED by the backend (scistack_gui.api.wire_schema, one
 * owner: each Handler's pydantic request model). This script is the ONE
 * place the TypeScript is made from it, so `npm run gen:types` and the
 * currency test (generatedTypes.test.ts) cannot format it differently.
 *
 * Usage: npm run gen:types   (or python scistack-gui/tools/gen_ts_types.py)
 */

import { readFileSync, writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

import { compile } from 'json-schema-to-typescript'

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..')
export const SCHEMA_FILE = join(ROOT, 'src', 'generated', 'api-schema.json')
export const TYPES_FILE = join(ROOT, 'src', 'generated', 'api-types.ts')

const BANNER = `/* eslint-disable */
/**
 * GENERATED by scistack-gui/frontend/scripts/gen-types.mjs from
 * api-schema.json, which is GENERATED from the backend's handler table
 * (scistack_gui.api.wire_schema). Do not edit: run
 * \`python scistack-gui/tools/gen_ts_types.py\`.
 */`

/** The TypeScript text for the schema at `schemaFile`. */
export async function generate(schemaFile = SCHEMA_FILE) {
  const schema = JSON.parse(readFileSync(schemaFile, 'utf8'))
  return compile(schema, 'ApiParams', {
    bannerComment: BANNER,
    additionalProperties: false,
    unreachableDefinitions: true,
    format: true,
    style: { singleQuote: true, semi: false, printWidth: 100 },
  })
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  const text = await generate()
  writeFileSync(TYPES_FILE, text)
  console.log(`wrote ${TYPES_FILE}`)
}
